package com.preppulse.service;
import com.preppulse.dto.DashboardInsights; import com.preppulse.model.FocusSession; import com.preppulse.repository.FocusSessionRepository; import com.preppulse.repository.StudyTaskRepository;
import org.springframework.stereotype.Service; import java.time.*; import java.time.temporal.TemporalAdjusters; import java.util.*; @Service public class InsightsService {
 private final FocusSessionRepository focusRepo; private final StudyTaskRepository taskRepo; private final RevisionService revision;
 public InsightsService(FocusSessionRepository f,StudyTaskRepository t,RevisionService r){focusRepo=f;taskRepo=t;revision=r;}
 public DashboardInsights get(){LocalDate today=LocalDate.now();LocalDateTime startToday=today.atStartOfDay(),now=LocalDateTime.now(),weekStart=today.with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY)).atStartOfDay();List<FocusSession> todaySessions=focusRepo.findBySessionTypeAndStartedAtBetweenOrderByStartedAtDesc("FOCUS",startToday,now);List<FocusSession> week=focusRepo.findBySessionTypeAndStartedAtBetweenOrderByStartedAtDesc("FOCUS",weekStart,now);int todayMinutes=todaySessions.stream().mapToInt(FocusSession::getDurationMinutes).sum();int weekMinutes=week.stream().mapToInt(FocusSession::getDurationMinutes).sum();Map<String,Integer> totals=new HashMap<>();for(FocusSession s:week){String subject=s.getTask()==null?"General study":s.getTask().getSubject();totals.merge(subject,s.getDurationMinutes(),Integer::sum);}List<DashboardInsights.SubjectMinutes> subjects=totals.entrySet().stream().sorted(Map.Entry.<String,Integer>comparingByValue().reversed()).limit(4).map(e->new DashboardInsights.SubjectMinutes(e.getKey(),e.getValue())).toList();int postponed=taskRepo.findAll().stream().mapToInt(t->t.getPostponedCount()).sum();int overdue=(int)taskRepo.findByCompletedFalse().stream().filter(t->t.getDueAt().isBefore(now)).count();return new DashboardInsights(todayMinutes,weekMinutes,week.size(),postponed,(int)revision.countDue(),overdue,subjects);}
}
